window.STORY_CHAPTERS["ca8c2cfe1ce0ac884"]={"id":"ca8c2cfe1ce0ac884","lines":[{"uid":"talk.ch6_2_1101#originalText","id":"talk.ch6_2_1101","speaker":{"cn":"桂妮拉","en":"Quinella","ja":"クィネラ"},"text":{"cn":"我是支配者，也是管理者……","en":"From this day forth I shall be the Pontifex","ja":"私は支配者にして管理者……"},"kind":"dialogue"},{"uid":"talk.ch6_2_1101_2#originalText","id":"talk.ch6_2_1101_2","speaker":{"cn":"桂妮拉","en":"Quinella","ja":"クィネラ"},"text":{"cn":"从今天开始我就是公理教会最高司祭， 亚多米尼史特蕾达。","en":"Administrator of the Axiom Church.","ja":"今日より私は公理教会最高司祭アドミニストレータである"},"kind":"dialogue"},{"uid":"talk.ch6_2_1102#originalText","id":"talk.ch6_2_1102","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……就这样， 在亚多米尼史特蕾达的绝对统治下， 和平且无为的时代一直持续下去。","en":"And so, under the supreme rule of this Administrator, years of peace and idleness continued.","ja":"……こうして、絶対者アドミニストレータの統治下で平和かつ無為な時代が長く続くこととなった"},"kind":"dialogue"},{"uid":"talk.ch6_2_1103#originalText","id":"talk.ch6_2_1103","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"但在桂妮拉成为亚多米尼史特蕾达的","en":"But 70 years after becoming Administrator,","ja":"しかし、クィネラがアドミニストレータとなってから70年後"},"kind":"dialogue"},{"uid":"talk.ch6_2_1103_2#originalText","id":"talk.ch6_2_1103_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"七十年后，她便感觉到自己的身体 出现了异变。","en":"she became aware that she was changing inside.","ja":"彼女は己に何らかの異変が起きたことを自覚した"},"kind":"dialogue"},{"uid":"talk.ch6_2_1104#originalText","id":"talk.ch6_2_1104","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"原来保存她记忆的空间容量， 也就是《灵魂容量》， 已经到达极限了。","en":"Her soul's \"capacity\" for storing memories had reached its limit.","ja":"彼女の記憶を保持するための領域の容量、いわば《魂の容量》が限界に達していた"},"kind":"dialogue"},{"uid":"talk.ch6_2_1105#originalText","id":"talk.ch6_2_1105","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"于是，亚多米尼史特蕾达她……","en":"It was then that the Administrator schemed to latch onto another soul...","ja":"そこで、アドミニストレータは"},"kind":"dialogue"},{"uid":"talk.ch6_2_1106#originalText","id":"talk.ch6_2_1106","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"计划侵占系统访问权限比其他人高的 家具行女儿的灵魂。","en":"The soul of a merchant's daughter, who had a higher system access authority than others.","ja":"他人より高いシステム・アクセス権限を持つ家具屋の娘の魂を乗っ取る計画を立てた"},"kind":"dialogue"},{"uid":"talk.ch6_2_1107#originalText","id":"talk.ch6_2_1107","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"她编出代表统整灵魂与记忆 的《合成秘仪》，","en":"She created the \"Synthesis Ritual,\" a fusing of souls and memories.","ja":"魂と記憶の統合を意味する《シンセサイズの秘儀》を編み出し"},"kind":"dialogue"},{"uid":"talk.ch6_2_1108#originalText","id":"talk.ch6_2_1108","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"成功夺取了别人的摇光。","en":"She had succeeded in hijacking another person's fluctlight...","ja":"他人のフラクトライトを強奪することに成功した"},"kind":"dialogue"},{"uid":"talk.ch6_2_1109#originalText","id":"talk.ch6_2_1109","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"可是， 那正是亚多米尼史特蕾达的失败之处。","en":"But that was her downfall.","ja":"ただ、それこそがアドミニストレータの失敗だった"},"kind":"dialogue"},{"uid":"talk.ch6_2_1110#originalText","id":"talk.ch6_2_1110","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"转移到家具行女儿身上的那一瞬间…… 出现了两名拥有相同权限的神明──","en":"For just a second, when she took over the girl...two gods with the same authority were created.","ja":"家具屋の娘に乗り移った一瞬だけ……同等の権限を持つ神がふたり存在してしまった――"},"kind":"dialogue"},{"uid":"talk.ch6_2_1111#originalText","id":"talk.ch6_2_1111","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"Cardinal System拥有主程序和副程序 这两组内核程序。","en":"The Cardinal System has two core programs: Main and Sub.","ja":"カーディナル・システムはメインとサブのふたつのコアプログラムを持っており"},"kind":"dialogue"},{"uid":"talk.ch6_2_1112#originalText","id":"talk.ch6_2_1112","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"主要处理程序在控制平衡时， 副处理程序会检查主进程的错误。","en":"The Main process controls balance, while the Sub process error-checks the Main.","ja":"メインプロセスがバランス制御を行っているあいだサブプロセスがメインのエラーチェックをする"},"kind":"dialogue"},{"uid":"talk.ch6_2_1113#originalText","id":"talk.ch6_2_1113","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"桂妮拉的摇光里……","en":"When Quinella edited her fluctlight,","ja":"クィネラがフラクトライトに刻み込んでしまったのは"},"kind":"dialogue"},{"uid":"talk.ch6_2_1114#originalText","id":"talk.ch6_2_1114","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不止写入了主要处理程序给予的命令 《维持秩序》，","en":"\"Maintain Order\" wasn't the only command written in there.","ja":"メインプロセスに与えられた命令《秩序の維持》だけでなく"},"kind":"dialogue"},{"uid":"talk.ch6_2_1115#originalText","id":"talk.ch6_2_1115","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"还有副处理程序给予的第二个命令， 《修正主要处理程序的错误》。","en":"The Sub processes' \"error-check\" command was also written in. Technically, two commands.","ja":"サブプロセスに与えられた命令《メインプロセスの過ちを正せ》のふたつだった"},"kind":"dialogue"},{"uid":"talk.ch6_2_1116#originalText","id":"talk.ch6_2_1116","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"拷贝灵魂到家具行女儿身上， 出现了两个完全相同的人， 结果就是──","en":"When the duplication of her soul into the girl was complete, and two copies of one person...","ja":"家具屋の娘への魂の複製が完了し同一の人間がふたり存在した結果――"},"kind":"dialogue"},{"uid":"talk.ch6_2_1117#originalText","id":"talk.ch6_2_1117","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"拷贝到家具行女儿身上的 摇光早一步崩溃，","en":"existed simultaneously, the fluctlight copied into the girl collapsed,","ja":"家具屋の娘にコピーされたほうのフラクトライトが崩壊し"},"kind":"dialogue"},{"uid":"talk.ch6_2_1118#originalText","id":"talk.ch6_2_1118","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"副人格的卡迪娜尔掌握了支配权。","en":"Cardinal, the sub-personality, then gained control.","ja":"副人格であるカーディナルが支配権を確立した"},"kind":"dialogue"},{"uid":"talk.ch6_2_1119#originalText","id":"talk.ch6_2_1119","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"随后，亚多米尼史特蕾达与卡迪娜尔 展开了一场殊死战。","en":"Then she and Administrator dueled.","ja":"そして、アドミニストレータとカーディナルは死闘を繰り広げた"},"kind":"dialogue"},{"uid":"talk.ch6_2_1120#originalText","id":"talk.ch6_2_1120","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"两个拥有同等级系统访问权限的人 若要战斗，","en":"With both of them being the same class with the same system access authority,","ja":"同クラスのシステム・アクセス権限を持つふたりが戦えば"},"kind":"dialogue"},{"uid":"talk.ch6_2_1121#originalText","id":"talk.ch6_2_1121","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"率先击中对方的卡迪娜尔 应该会获得胜利。","en":"Cardinal, who got in the first attack, should have won.","ja":"先制攻撃に成功したカーディナルが勝利するはずだった"},"kind":"dialogue"},{"uid":"talk.ch6_2_1122#originalText","id":"talk.ch6_2_1122","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"但是， 亚多米尼史特蕾达把房间指定为 禁止使用系统指令的空间。","en":"But Administrator set the room at an address where System Commands were forbidden.","ja":"しかし、アドミニストレータは部屋をシステム・コマンド禁止アドレスに指定し"},"kind":"dialogue"},{"uid":"talk.ch6_2_1123#originalText","id":"talk.ch6_2_1123","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"她选择利用武器作战， 向体格较为不利的卡迪娜尔发动攻击。","en":"The fight was settled by weapons. Cardinal, being of smaller stature, naturally lost.","ja":"武器による戦いで体格差のあるカーディナルを攻撃した"},"kind":"dialogue"},{"uid":"talk.ch6_2_1124#originalText","id":"talk.ch6_2_1124","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"卡迪娜尔选择撤退， 逃到了这座与外界 完全隔离的大图书馆里。","en":"And so she withdrew, hiding herself in this library, isolated from the outside world.","ja":"カーディナルはこの大図書室に撤退し外界とのつながりを完全に遮断した"},"kind":"dialogue"},{"uid":"talk.ch6_2_1125#originalText","id":"talk.ch6_2_1125","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"之后的两百年， 亚多米尼史特蕾达为了 预防卡迪娜尔的袭击，","en":"For the next 200 years, Administrator readied herself for Cardinal's next attack.","ja":"以来200年、アドミニストレータはカーディナルからの襲撃に備え"},"kind":"dialogue"},{"uid":"talk.ch6_2_1126#originalText","id":"talk.ch6_2_1126","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"将名为《敬神模块》的物品 埋进人界罪犯的身体里， 并使用合成秘仪，","en":"She buried what is called a Piety Module into sinners of the Human Realm, using the Synthesis Ritual.","ja":"人界の罪人に《パイエティモジュール》なるオブジェクトを埋め込みシンセサイズの秘儀を使い"},"kind":"dialogue"},{"uid":"talk.ch6_2_1127#originalText","id":"talk.ch6_2_1127","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"创造出对她绝对忠诚， 而且致力维持人界现状的 《集成骑士》。","en":"This created Integrity Knights, absolutely loyal fighters who keep the human world exactly as it is.","ja":"絶対の忠誠と人界の現状維持を保つ《整合騎士》を生み出す"},"kind":"dialogue"},{"uid":"talk.ch6_2_1128#originalText","id":"talk.ch6_2_1128","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"另一方面，卡迪娜尔为了可再次见到亚多米尼史特蕾达， 不断地观察与思索，","en":"Meanwhile, Cardinal spent the years in observation and study to plan her attack.","ja":"一方、カーディナルはアドミニストレータと再び相見えるために観察と思索を重ね"},"kind":"dialogue"},{"uid":"talk.ch6_2_1129#originalText","id":"talk.ch6_2_1129","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"为了寻找帮手，对周围栖息的昆虫鸟雀施加《感觉共享》的法术后，把牠们放到整个世界。","en":"She cast \"Sensory Sharing\" on the birds and insects of the world, to try and find herself allies.","ja":"協力者を探すべく周囲に生息する鳥や虫に《感覚共有》の術を施して全世界に放った"},"kind":"dialogue"},{"uid":"talk.ch6_2_1130#originalText","id":"talk.ch6_2_1130","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呜哇！？","en":"Agh?!","ja":"うわっ!?"},"kind":"dialogue"},{"uid":"talk.ch6_2_1131#originalText","id":"talk.ch6_2_1131","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"她叫作夏洛特。","en":"Her name is Charlotte.","ja":"名前はシャーロットじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_1132#originalText","id":"talk.ch6_2_1132","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"从你和尤吉欧离开卢利特村开始， 她就一直在观察你们两个的言行举止。","en":"Ever since you and Eugeo left Rulid Village, she's been watching your every move.","ja":"おぬしとユージオがルーリッドの村を出たその時からずーっとおぬしらふたりの言動を見聞きしておった"},"kind":"dialogue"},{"uid":"talk.ch6_2_1133#originalText","id":"talk.ch6_2_1133","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……不过除了观察之外， 好像偶尔也会有别的行动。","en":"Though it seems she did more than watch here and there...","ja":"……たまには見る以外のこともしていたようじゃが"},"kind":"dialogue"},{"uid":"talk.ch6_2_1134#originalText","id":"talk.ch6_2_1134","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"从集成骑士手底下逃走时， 告诉我该往哪里逃的是……","en":"When I was running from the Integrity Knight and a voice showed me the way...","ja":"整合騎士から逃げている時道を教えてくれたのは……"},"kind":"dialogue"},{"uid":"talk.ch6_2_1135#originalText","id":"talk.ch6_2_1135","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"对、对了，难道……","en":"Th-that's right! Could it also be...","ja":"そ、そうだ、もしかすると……"},"kind":"dialogue"},{"uid":"talk.ch6_2_1136#originalText","id":"talk.ch6_2_1136","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"赛菲利雅花苞全部被砍断的时候， 鼓励我的也是妳吗……？","en":"When all my Zephyrias were cut... were you the one who consoled me?","ja":"ゼフィリアの蕾を全部切られた時俺を励ましてくれたのも君なのか……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_1137#originalText","id":"talk.ch6_2_1137","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"夏洛特是我施加术式后， 派遣到人界各地的最古老监视用个体。","en":"Charlotte is the most ancient of the observation units that I released into the human realm.","ja":"シャーロットはわしが術式を施し人界各地に放った最古の監視用ユニットじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_1138#originalText","id":"talk.ch6_2_1138","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"她漫长的任务现在终于结束了。","en":"Her long, long mission has finally come to an end.","ja":"長い、長い任務もこれでようやく終わりじゃな"},"kind":"dialogue"},{"uid":"talk.ch6_2_1139#originalText","id":"talk.ch6_2_1139","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"她已经工作两百年以上了啊……","en":"She's been working for me for 200 years now...","ja":"もう200年以上も働いてもらったか……"},"kind":"dialogue"},{"uid":"talk.ch6_2_1140#originalText","id":"talk.ch6_2_1140","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"──谢谢妳。","en":"Thank you.","ja":"――ありがとう"},"kind":"dialogue"},{"uid":"talk.ch6_2_1141#originalText","id":"talk.ch6_2_1141","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"妳…… 一直被关在这座大图书馆里，","en":"So... All this time, while you were barricaded in the Great Library,","ja":"あんたは……この大図書室に閉じこもったまま"},"kind":"dialogue"},{"uid":"talk.ch6_2_1142#originalText","id":"talk.ch6_2_1142","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"两百多年来就利用这些使魔作为耳目， 寻找能够帮助妳的人吗……","en":"You spent 200 years, borrowing the eyes and ears of animals, to find a partner to help you?","ja":"使い魔の眼と耳を通して協力者になり得る人間を200年以上も捜し続けていたのか……"},"kind":"dialogue"},{"uid":"talk.ch6_2_1143#originalText","id":"talk.ch6_2_1143","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"嗯。","en":"Indeed.","ja":"うむ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2101#originalText","id":"talk.ch6_2_2101","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"妳…… 一直被关在这座大图书馆里，","en":"So... All this time, while you were barricaded in the Great Library,","ja":"あんたは……この大図書室に閉じこもったまま"},"kind":"dialogue"},{"uid":"talk.ch6_2_2102#originalText","id":"talk.ch6_2_2102","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"两百多年来就利用这些使魔作为耳目， 寻找能够帮助妳的人吗……","en":"You spent 200 years, borrowing the eyes and ears of animals, to find a partner to help you?","ja":"使い魔の眼と耳を通して協力者になり得る人間を200年以上も捜し続けていたのか……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2103#originalText","id":"talk.ch6_2_2103","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"嗯。","en":"Indeed.","ja":"うむ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2104#originalText","id":"talk.ch6_2_2104","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不过， 在我如此观看世界的期间， 连我自己都产生一种想法。","en":"But even as I observed this world, I couldn't help but wonder...","ja":"しかしそうして世界を眺めておるあいだにさすがのわしも思ったよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2105#originalText","id":"talk.ch6_2_2105","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"觉得自己为什么要做这种事情呢……","en":"Why am I trying to do this?","ja":"わしはなぜこのようなことをしておるのじゃろう、とな……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2106#originalText","id":"talk.ch6_2_2106","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2107#originalText","id":"talk.ch6_2_2107","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"为什么创造这个世界的外界诸神， 完全不管假神亚多米尼史特蕾达的 专横呢……","en":"Why would the gods who built this world let Administrator, a false god, keep her tyrannical rule?","ja":"なぜ、この世界を造った外界の神たちは、偽りの神アドミニストレータの専横を放置しているのか……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2108#originalText","id":"talk.ch6_2_2108","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我边思考， 边参考Cardinal System内置数据库，","en":"As I plunged into the database embedded in the Cardinal System,","ja":"考えながらカーディナル・システムに内蔵されたデータベースを参照していく中で"},"kind":"dialogue"},{"uid":"talk.ch6_2_2108_2#originalText","id":"talk.ch6_2_2108_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"然后得到了一个答案。","en":"I reached one conclusion.","ja":"ひとつの答えに思い至った"},"kind":"dialogue"},{"uid":"talk.ch6_2_2109#originalText","id":"talk.ch6_2_2109","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"那就是真正的神明RATH不希望 这个世界的人民过着幸福的生活。","en":"Rath, our true God, does not wish for the people of this world to be prosperous or happy.","ja":"真の神たるラースはこの世界の人間たちの幸福な営みなど望んではおらぬのだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2110#originalText","id":"talk.ch6_2_2110","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不如说完全相反…… 他们在用巨大钳子慢慢箝制人民。","en":"If anything, it's the opposite. They are crushing us slowly.","ja":"むしろその逆……民たちを巨大な万力でゆっくり、ゆっくりと締め上げて"},"kind":"dialogue"},{"uid":"talk.ch6_2_2111#originalText","id":"talk.ch6_2_2111","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"他们是为了观察人民 在这种负荷下如何挣扎， 才会让这个世界存在。","en":"They merely observe as they torture us, to see how we will resist them.","ja":"その負荷にどのように抗うのか観察するためにのみこの世界は存在する"},"kind":"dialogue"},{"uid":"talk.ch6_2_2112#originalText","id":"talk.ch6_2_2112","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………","en":"...","ja":"…………"},"kind":"dialogue"},{"uid":"talk.ch6_2_2113#originalText","id":"talk.ch6_2_2113","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"现在负荷也每天都在增加。终有一天，负荷实验最终阶段会来临，","en":"Their grip is tightening, day by day, until soon,","ja":"現在も負荷は日に日に増しておる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2113_2#originalText","id":"talk.ch6_2_2113_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"并成为最大的考验……","en":"the experiment will enter its final phase.","ja":"そしていずれ最大の試練として負荷実験の最終フェーズが訪れる……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2114#originalText","id":"talk.ch6_2_2114","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你应该也知道人界外面有什么吧。","en":"You surely know what exists outside the Human Realm.","ja":"おぬしも知っておろう人界の外に何があるか"},"kind":"dialogue"},{"uid":"talk.ch6_2_2115#originalText","id":"talk.ch6_2_2115","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"黑暗领域……？","en":"The Dark Territory?","ja":"ダークテリトリー……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2116#originalText","id":"talk.ch6_2_2116","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"没错。那个黑暗世界就是要给予人民 终极痛苦而制造的设备。","en":"Exactly. That world of darkness created to inflict agony on our citizens.","ja":"そうじゃ。かの闇の世界こそ民たちに究極の苦しみを与えるべく作られた装置"},"kind":"dialogue"},{"uid":"talk.ch6_2_2117#originalText","id":"talk.ch6_2_2117","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"哥布尔、半兽人以及其他种族跟人类","en":"The fluctlights of Goblins, Orcs","ja":"ゴブリン、オーク、その他の種族は"},"kind":"dialogue"},{"uid":"talk.ch6_2_2117_2#originalText","id":"talk.ch6_2_2117_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"是一样的存在，但摇光里被烙印了 杀戮与强夺的行动原理。","en":"and other monsters are programmed to slaughter and plunder.","ja":"人間と同じフラクトライトに殺戮と強奪の行動原理を付与された存在じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2118#originalText","id":"talk.ch6_2_2118","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"这个集团每天都在期待攻入人类的 领土、残暴肆虐的日子到来。","en":"Bands of these monsters are waiting,","ja":"その集団が、人界人の領土に攻め入り暴虐の限りを尽くす日を待っておる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2118_2#originalText","id":"talk.ch6_2_2118_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我想这是不久之后就会发生的事。","en":"ready to invade human lands any day now.","ja":"そう遠い未来の話ではないぞ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2119#originalText","id":"talk.ch6_2_2119","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……亚多米尼史特蕾达知道负荷实验的 最终阶段最近就要开始了吗？","en":"Does Administrator know about this final phase of the experiment?","ja":"……アドミニストレータは、近いうちにその負荷実験の最終フェーズが始まることを知っているのか?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2120#originalText","id":"talk.ch6_2_2120","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"那家伙认为光靠自己和三十名集成骑士 就能顺利解决掉暗之军队。","en":"She arrogantly believes that an army of herself and 30 Integrity Knights can keep them at bay.","ja":"あやつは、己と30人の整合騎士のみで闇の軍勢を問題なく撃退できるとタカをくくっておる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2121#originalText","id":"talk.ch6_2_2121","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"连当那一刻来临时， 将成为宝贵战力的东西南北守护龙，","en":"She is so ignorant that she killed the dragons of the north, south, east, and west","ja":"その時が来た時貴重な戦力となってくれるはずじゃった"},"kind":"dialogue"},{"uid":"talk.ch6_2_2122#originalText","id":"talk.ch6_2_2122","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"都因为自己无法操纵的理由 而被她杀掉了。","en":"because she couldn't control them, even though they would have been our salvation.","ja":"東西南北の守護竜すらも己の操作が効かぬという理由で屠ってしまうほどにな"},"kind":"dialogue"},{"uid":"talk.ch6_2_2123#originalText","id":"talk.ch6_2_2123","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……可是， 单靠他们是赢不了暗之军队的。","en":"But the Integrity Knights alone are too few in number to defeat","ja":"……だがあやつらだけで闇の軍勢に勝つことは不可能じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2123_2#originalText","id":"talk.ch6_2_2123_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"集成骑士的人数绝对太少。","en":"the forces of darkness.","ja":"整合騎士たちは絶対数が少なすぎる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2124#originalText","id":"talk.ch6_2_2124","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"等……等一下。","en":"W-wait a minute now!","ja":"ちょ……ちょっと待ってくれよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2125#originalText","id":"talk.ch6_2_2125","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这也就是说…… 不论有没有打倒亚多米尼史特蕾达，","en":"Are you saying that, regardless of whether or not Administrator is defeated,","ja":"てことは……アドミニストレータを倒そうと倒すまいと"},"kind":"dialogue"},{"uid":"talk.ch6_2_2126#originalText","id":"talk.ch6_2_2126","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个世界将来的命运还是 不会有任何改变吗？","en":"This world is still doomed?","ja":"結局この世界の辿る運命は変わらないんじゃないのか?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2127#originalText","id":"talk.ch6_2_2127","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"没错。事到如今， 连我也没有办法阻止 来自黑暗领域的侵略。","en":"Exactly. At present, I cannot find the means to stop the Dark Territory's invasion.","ja":"その通りじゃ。ことここに至ってはわしにももうダークテリトリーからの侵略を止める手段はない"},"kind":"dialogue"},{"uid":"talk.ch6_2_2128#originalText","id":"talk.ch6_2_2128","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……也就是说…… 只要能达成妳的目的， 也就是消除亚多米尼史特蕾达，","en":"In other words... you only care about your mission to delete Administrator...","ja":"……つまり……カーディナル、あんたはアドミニストレータを消去するという目的を果たせれば"},"kind":"dialogue"},{"uid":"talk.ch6_2_2129#originalText","id":"talk.ch6_2_2129","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"妳之后就不管这个世界的死活了…… 妳的意思是这样吗……？","en":"You don't know or care what will happen to this world afterwards?","ja":"そのあと、この世界がどうなろうと知ったことじゃないと……そう言うのか……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2130#originalText","id":"talk.ch6_2_2130","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……或许是吧。","en":"That may be true...","ja":"……そうかもしれない"},"kind":"dialogue"},{"uid":"talk.ch6_2_2131#originalText","id":"talk.ch6_2_2131","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"可是我绝对不承认…… RATH这种将世界导向末日的神明。","en":"But one thing is clear: I cannot accept Rath as my God when they engineered the end of the world.","ja":"しかしわしは世界の終末を仕組んだラースを……そんな神を、断じて認めぬ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2132#originalText","id":"talk.ch6_2_2132","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我无论如何都无法接受这样的结局。因此……我做出了唯一的结论。","en":"I could not accept that end. That was how I reached the only conclusion I could.","ja":"そのような結末などどうあろうと容認できぬゆえに…わしは、唯一の結論に至ったのじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2133#originalText","id":"talk.ch6_2_2133","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我要想尽办法在那一刻来临之前排除 亚多米尼史特蕾达，","en":"Before Rath ends the world, I will delete Administrator,","ja":"何としてもその時が来る前にアドミニストレータを排除し"},"kind":"dialogue"},{"uid":"talk.ch6_2_2133_2#originalText","id":"talk.ch6_2_2133_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"恢复我身为 Cardinal System的权限……","en":"restore my authority as the Cardinal System,","ja":"カーディナル・システムとしての権限を回復して……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2134#originalText","id":"talk.ch6_2_2134","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"然后把Underworld， 不管是人界还是黑暗领域， 全都化为无。","en":"and return the Human Realm, the Dark Territory, the entirety of Underworld, to nothingness.","ja":"アンダーワールドを人界も、ダークテリトリーも全てまとめて無に還すと"},"kind":"dialogue"},{"uid":"talk.ch6_2_2135#originalText","id":"talk.ch6_2_2135","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"化为……无……？","en":"Return to...nothingness?","ja":"無に……還す……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2136#originalText","id":"talk.ch6_2_2136","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"就是字面上的意思啊。","en":"Just as it sounds,","ja":"言葉どおりじゃよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2136_2#originalText","id":"talk.ch6_2_2136_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我要把保存在LightCube Cluster 这个灵魂摇篮里头的所有摇光都删除。","en":" I will erase all the fluctlights stored in the Lightcube Cluster,","ja":"魂の揺りかごたるライトキューブ・ クラスターに保存されている全てのフラクトライトを削除するのじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2137#originalText","id":"talk.ch6_2_2137","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不论是人界还是暗之国的人民， 我会把他们一个不留地都删掉。","en":"leaving not one fluctlight, human or monster, alive.","ja":"人界の民のものも、闇の民のものも、ひとつ残らず"},"kind":"dialogue"},{"uid":"talk.ch6_2_2138#originalText","id":"talk.ch6_2_2138","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………","en":"...","ja":"…………"},"kind":"dialogue"},{"uid":"talk.ch6_2_2139#originalText","id":"talk.ch6_2_2139","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"桐人， 如果你协助我取回所有权限，","en":"Kirito. If you help me regain all of my authority,","ja":"キリトよおぬしの助力によりわしが全権限を取り戻せたら"},"kind":"dialogue"},{"uid":"talk.ch6_2_2140#originalText","id":"talk.ch6_2_2140","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"在消灭Underworld之前， 我就实现你一部分的愿望吧。","en":"I can grant you a wish before I delete Underworld.","ja":"アンダーワールドを消滅させる前に限定的ではあるがおぬしの望みを叶えよう"},"kind":"dialogue"},{"uid":"talk.ch6_2_2141#originalText","id":"talk.ch6_2_2141","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……？","en":"...?","ja":"……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2142#originalText","id":"talk.ch6_2_2142","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"只要你指定想拯救的人， 我就不消除那些人的摇光， 而是冻结后并保留下来。","en":"Give me the names of those you want spared, I can archive their fluctlights and not delete them.","ja":"助けたいと思う者の名を指定すればその者たちのフラクトライトは消去せず、凍結させたまま残す"},"kind":"dialogue"},{"uid":"talk.ch6_2_2143#originalText","id":"talk.ch6_2_2143","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"如果保留十个人左右， 在你回到外部世界后，","en":"If it's up to ten, you can secure their lightcubes once","ja":"10個程度であればおぬしが外部世界に脱出したのちに"},"kind":"dialogue"},{"uid":"talk.ch6_2_2143_2#originalText","id":"talk.ch6_2_2143_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"应该能拿到他们的LightCube吧。","en":"you're back in the outside world.","ja":"そのライトキューブを確保することもできよう"},"kind":"dialogue"},{"uid":"talk.ch6_2_2144#originalText","id":"talk.ch6_2_2144","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………！","en":"...!","ja":"…………!"},"kind":"dialogue"},{"uid":"talk.ch6_2_2145#originalText","id":"talk.ch6_2_2145","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我……我实在……","en":"I...I have...","ja":"俺……俺には……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2201#originalText","id":"talk.ch6_2_2201","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"卡迪娜尔……妳说过妳的灵魂 是桂妮拉的拷贝品对吧……？","en":"Cardinal... You told me your soul was sort of a copy of Quinella's, correct?","ja":"カーディナル……あんたは自分の魂はクィネラのコピーだと、そう言ったよな……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2202#originalText","id":"talk.ch6_2_2202","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"嗯， 确实是这样没错。","en":"Indeed. Literally a copy.","ja":"うむ如何にもその通りじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2203#originalText","id":"talk.ch6_2_2203","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那么……妳应该也流有贵族的纯血， 应该也拥有只追求自己的利益与","en":"Then you must have pure noble blood in your veins.","ja":"なら……あんたにも純粋なる貴族の血が流れているはずだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2203_2#originalText","id":"talk.ch6_2_2203_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"欲望的基因才对……","en":"The genes that only seek power and profit.","ja":"己の利益と欲望のみを追求する遺伝子が……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2204#originalText","id":"talk.ch6_2_2204","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"但妳为什么没有丢下这一切， 然后逃走呢？","en":"So why didn't you try to abandon everything and escape?","ja":"なぜあんたは、全てを投げ出し逃げようとしなかったんだ?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2205#originalText","id":"talk.ch6_2_2205","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"为什么要独自一个人在这里 等了两百年呢……？","en":"How were you able to wait here all by yourself for 200 years?","ja":"なぜこんな場所でたったひとり200年も待ちつづけたんだよ……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2206#originalText","id":"talk.ch6_2_2206","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我的愿望就只有一个， 排除亚多米尼史特蕾达， 让世界恢复正常。","en":"I have but one wish: extinguishing Administrator, and normalizing this world.","ja":"わしの望みはただひとつアドミニストレータの排除と世界の正常化じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2207#originalText","id":"talk.ch6_2_2207","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"对现在的我来说， 只有将一切化为虚无， 才能实现让世界恢复正常的愿望。","en":"In my view, a world cannot be normalized unless it is returned to nothingness.","ja":"わしにとっては、もはや正常なる世界とは完全なる虚無に還すこと以外に実現できぬのじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2208#originalText","id":"talk.ch6_2_2208","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……不对……不是这样…… 我……我也有唯一一个欲望……","en":"No... Perhaps that's not entirely correct... I do have my own desire. Just one desire...","ja":"……いや……違うかな……わしにも……わしにも欲望はある、たったひとつ……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2209#originalText","id":"talk.ch6_2_2209","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"这两百年来…… 我有件无论如何都想知道的事情……","en":"During these 200 years...there was just one thing I wished I could find out...","ja":"この200年……どうしても知りたかったことが……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2210#originalText","id":"talk.ch6_2_2210","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……喂，桐人， 你过来这里。","en":"Hey, Kirito. Come here.","ja":"……おいキリト、こっちに来い"},"kind":"dialogue"},{"uid":"talk.ch6_2_2211#originalText","id":"talk.ch6_2_2211","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"什么……？","en":"Huh...?","ja":"は……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2212#originalText","id":"talk.ch6_2_2212","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"再前面一点。","en":"Further forward.","ja":"もっと前じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2213#originalText","id":"talk.ch6_2_2213","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦咦？","en":"Huh?!","ja":"ええ?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2214#originalText","id":"talk.ch6_2_2214","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"别啰啰嗦嗦的。","en":"Stop questioning me.","ja":"つべこべ言うな"},"kind":"dialogue"},{"uid":"talk.ch6_2_2215#originalText","id":"talk.ch6_2_2215","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"张开双臂。","en":"Raise your arms.","ja":"両手を広げろ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2216#originalText","id":"talk.ch6_2_2216","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………这样吗？","en":"Like...this?","ja":"…………こうか?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2217#originalText","id":"talk.ch6_2_2217","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"哼， 麻烦的家伙。","en":"Argh! Why are you so slow!?","ja":"ええい遠回りな奴じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2218#originalText","id":"talk.ch6_2_2218","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……………………","en":"...","ja":"……………………"},"kind":"dialogue"},{"uid":"talk.ch6_2_2219#originalText","id":"talk.ch6_2_2219","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"这样啊……原来这就是……","en":"I see... So this is it...","ja":"そうか……これが……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2220#originalText","id":"talk.ch6_2_2220","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……这就是人类吗？","en":"This is... what it feels like to be human.","ja":"……これが人間であるということか"},"kind":"dialogue"},{"uid":"talk.ch6_2_2221#originalText","id":"talk.ch6_2_2221","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……好温暖……","en":"So warm...","ja":"……あったかい……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2222#originalText","id":"talk.ch6_2_2222","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……终于……得到回报了…… 我的两百年…… 并没有错……","en":"At last... I am fulfilled... My 200-year-long wait was not in vain.","ja":"……やっと……報われた……わたしの、200年は……間違いじゃなかった……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2223#originalText","id":"talk.ch6_2_2223","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"光是知道这种温度…… 我就满足了…… 感觉自己收到充分的回报了……","en":"Just feeling this warmth has satisfied me... It is more than enough.","ja":"この温かさを知っただけで……わたしは満足……報われた、じゅうぶんに……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2224#originalText","id":"talk.ch6_2_2224","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你要在那里呆站到什么时候？","en":"Just how long are you going to stand there like a statue?","ja":"いつまでぼうっと突っ立っておるつもりじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2225#originalText","id":"talk.ch6_2_2225","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……变化太大了吧……","en":"Way to kill a mood...","ja":"……そりゃないよ……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2226#originalText","id":"talk.ch6_2_2226","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"──你做出结论了吗？ 究竟是要接受我的提案， 还是要拒绝？","en":"So, have you reached a decision? Will you accept my proposition?","ja":"――それで、結論は出たか?わしの提案に乗るかそれとも蹴るか"},"kind":"dialogue"},{"uid":"talk.ch6_2_2227#originalText","id":"talk.ch6_2_2227","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……好吧， 我接受妳的作战计划。不过……","en":"Okay, I accept your proposition. But...","ja":"……解ったあんたの作戦に乗るよ。でも……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2228#originalText","id":"talk.ch6_2_2228","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过，我不会放弃思考。即使开始战斗， 我也会继续寻找其他办法。","en":"I won't stop thinking about it. Even after the war has started, I'll keep looking for another way.","ja":"でも俺は、考えることはやめない戦いが始まっても、何か手段がないか探し続ける"},"kind":"dialogue"},{"uid":"talk.ch6_2_2229#originalText","id":"talk.ch6_2_2229","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我会想办法避免发生 负荷实验阶段的悲剧， 让世界和平地存在下去。","en":"I'll try to find a way to stop this tragic, immoral experiment, and bring peace to this world.","ja":"負荷実験段階の悲劇をどうにか回避して世界が平和に存続できるような解決法を"},"kind":"dialogue"},{"uid":"talk.ch6_2_2230#originalText","id":"talk.ch6_2_2230","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"唉，你怎么这么乐天啊。不过我早就知道你是这样的人了。","en":"Oh dear, your blind optimism is painful. Though I already knew this about you.","ja":"やれやれ、とんでもない楽天家じゃな解っておったことじゃが"},"kind":"dialogue"},{"uid":"talk.ch6_2_2231#originalText","id":"talk.ch6_2_2231","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……我不希望妳也消失啊。","en":"I don't want you to disappear.","ja":"……俺は、あんたにも消えて欲しくないんだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2232#originalText","id":"talk.ch6_2_2232","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果要我选十个人的话， 妳一定也会是其中一个。","en":"If I can choose ten people to save, you're definitely going to be one of them.","ja":"10人選べと言われたらそこにはあんたも入れるよ、間違いなく"},"kind":"dialogue"},{"uid":"talk.ch6_2_2233#originalText","id":"talk.ch6_2_2233","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"……你不只乐天，还很愚蠢。如果我跟着离开，","en":"Blindly optimistic and stupid. Answer me this;","ja":"……そのうえ、愚かな奴じゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2233_2#originalText","id":"talk.ch6_2_2233_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"要由谁来消除这个世界呢？","en":"if I escape, who will delete this world?","ja":"わしが脱出してしまったら誰がこの世界を消去するというのだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2234#originalText","id":"talk.ch6_2_2234","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"所以啦…… 我只是在说我理解这个情况， 但不会放弃挣扎。","en":"I'm saying, I understand the situation, but I won't give up without a fight.","ja":"だから……状況は理解したけど悪あがきは放棄しないって言ってるだけだよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2235#originalText","id":"talk.ch6_2_2235","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你…… 总有一天也会知道放弃的痛苦……","en":"Someday, you will have to learn as I did... The pain of surrender.","ja":"おぬしにも……いつかは諦めることの苦さを知る時が来る……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2236#originalText","id":"talk.ch6_2_2236","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不是指倾尽全力还无法成功……","en":"Not from fighting until you can’t stand anymore,","ja":"力尽くして及ばぬことではなく……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2236_2#originalText","id":"talk.ch6_2_2236_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"而是只能接受自己无法成功的推测……","en":"but from realizing failure is the only choice.","ja":"及ばぬであろうという推測を受け入れなくてはならぬ時が……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2300#originalText","id":"talk.ch6_2_2300","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"中央圣堂 大图书馆","en":"Central Cathedral - Great Library","ja":"セントラル・カセドラル 大図書室"},"kind":"caption"},{"uid":"talk.ch6_2_2301#originalText","id":"talk.ch6_2_2301","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"久等了， 抱歉丢下你一个人在这里。","en":"I'm back! Sorry I left you for so long.","ja":"お待たせ独りにして悪かったな"},"kind":"dialogue"},{"uid":"talk.ch6_2_2302#originalText","id":"talk.ch6_2_2302","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，嗯……","en":"Oh, yeah...","ja":"あ、うん……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2304#originalText","id":"talk.ch6_2_2304","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"卡迪娜尔也会协助我们对抗集成骑士。","en":"She's going to assist us in fighting the Integrity Knights.","ja":"俺たちが整合騎士連中と戦うのにカーディナルも協力してくれるそうだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2305#originalText","id":"talk.ch6_2_2305","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"协……协助……？","en":"H-help us?","ja":"き……協力……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2303_2#originalText","id":"talk.ch6_2_2303_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯。卡迪娜尔是被最高司祭亚多米尼史特蕾达放逐的另一名最高司祭。","en":"Yeah. Cardinal is another Pontifex who was exiled by the Pontifex Administrator.","ja":"ああ。カーディナルは最高司祭アドミニストレータに追放された、もうひとりの最高司祭だ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2306#originalText","id":"talk.ch6_2_2306","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是啊。这个人也有打倒亚多米尼史特蕾达， 重新当上最高司祭的目的。","en":"Yes. Her mission is to defeat Administrator and become the Pontifex again.","ja":"この人にもアドミニストレータを倒して最高司祭に復帰するという目的があるんだ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2307#originalText","id":"talk.ch6_2_2307","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"既然曾经是最高司祭， 那么妳知道爱丽丝……","en":"If you are the former Pontifex, then, Alice...","ja":"かつての最高司祭ということはじゃあ、アリス……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2308#originalText","id":"talk.ch6_2_2308","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"集成骑士的 爱丽丝‧辛赛西斯‧萨蒂……","en":"and the Integrity Knight, Alice Synthesis Thirty...","ja":"整合騎士のアリス・シンセシス・サーティが"},"kind":"dialogue"},{"uid":"talk.ch6_2_2309#originalText","id":"talk.ch6_2_2309","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"和爱丽丝‧滋贝鲁库 是不是同一个人吗？","en":"Do you know whether or not they're the same person?","ja":"アリス・ツーベルクと同一人物なのかどうかも知ってるんですか?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2310#originalText","id":"talk.ch6_2_2310","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"抱歉…… 我在这个地方能获得的 情报极为有限。","en":"I'm sorry, but the knowledge I can obtain here is limited.","ja":"すまんが……わしがこの場所で手に入れられる情報はごく限られておるのじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2311#originalText","id":"talk.ch6_2_2311","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"──不过， 我可以告诉你创造集成骑士的神圣术，","en":"But I can tell you how to undo the Synthesis Ritual,","ja":"――しかし、整合騎士を造り出すための神聖術"},"kind":"dialogue"},{"uid":"talk.ch6_2_2311_2#originalText","id":"talk.ch6_2_2311_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"《合成秘仪》的解除方法。","en":"the spell that creates Integrity Knights.","ja":"《シンセサイズの秘儀》を解除する方法ならば教えられる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2312#originalText","id":"talk.ch6_2_2312","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"只要除去插入他们额头当中的 《敬神模块》就可以了。它的外观是三角柱……","en":"You must remove the Piety Modules from their foreheads. They look like prisms.","ja":"彼らの額から挿入された《パイエティモジュール》を除去すればよい。見た目は三角柱で……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2313#originalText","id":"talk.ch6_2_2313","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是那时候的……","en":"Like that thing we saw...","ja":"あのときの……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2314#originalText","id":"talk.ch6_2_2314","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"敬神模块是为了阻碍记忆的链接 而插入的。","en":"Piety Modules are installed in such a way that memories are blocked.","ja":"パイエティモジュールは記憶の繋がりを阻害する形で挿入されておる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2315#originalText","id":"talk.ch6_2_2315","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"它能够封印集成骑士的过去，","en":"They seal an Integrity Knight's","ja":"それにより、整合騎士となる者の過去を封じ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2315_2#originalText","id":"talk.ch6_2_2315_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"同时强迫他们绝对效忠于 公理教会与最高司祭。","en":"past and imbue them with a high level of fealty for the Pontifex.","ja":"同時に公理教会と最高司祭への絶対の忠誠を強いておるのじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2316#originalText","id":"talk.ch6_2_2316","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"也就是说…… 只要刺激集成骑士过去的记忆 就能解开术式啰？","en":"So...to break the spell, we just need to jog the Integrity Knights’ past memories?","ja":"つまり……術を解くには整合騎士の過去の記憶を揺さぶってやればいい、ってことか?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2317#originalText","id":"talk.ch6_2_2317","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不……这样还不够， 还有另一个不可或缺的东西。","en":"No, that alone is not enough. There is one more crucial step:","ja":"いや……それだけでは不十分じゃもうひとつ、絶対に必要なものがある"},"kind":"dialogue"},{"uid":"talk.ch6_2_2318#originalText","id":"talk.ch6_2_2318","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"就是模块插入前存在于该处的东西， 也就是对集成骑士来说最重要的 记忆碎片。","en":"Returning the Knight's dearest memory fragment. It is removed to make room for the Module.","ja":"モジュールが挿入されておる場所に本来存在したもの整合騎士にとっていちばん大切な記憶の欠片じゃよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2319#originalText","id":"talk.ch6_2_2319","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"记忆碎片……但是， 亚多米尼史特蕾达说不定已经 破坏掉从骑士那里夺走的碎片了。","en":"Memory fragments... But she might have destroyed them after removing them.","ja":"記憶の欠片……。でもアドミニストレータは騎士から抜き取ったそれを破棄しているかもしれない"},"kind":"dialogue"},{"uid":"talk.ch6_2_2320#originalText","id":"talk.ch6_2_2320","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"不，亚多米尼史特蕾达是个 谨慎的女人，应该不会破坏 可能还有用的东西。","en":"No, Administrator is pragmatic. She would not destroy something that might become useful.","ja":"いや、アドミニストレータは慎重な女じゃ何かに使えそうなものを破棄したりはせぬじゃろう"},"kind":"dialogue"},{"uid":"talk.ch6_2_2321#originalText","id":"talk.ch6_2_2321","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"她一定是把它们…… 保存在自己位于中央圣堂最上层的 寝室里了。","en":"She would save these memory fragments in her room on the Central Cathedral's top floor.","ja":"まず間違いなく、自らの居室……セントラル・カセドラル最上階に保管しておるはず"},"kind":"dialogue"},{"uid":"talk.ch6_2_2322#originalText","id":"talk.ch6_2_2322","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"也就是说……要让集成骑士恢复原状， 就需要到达最上层才行吗……","en":"So, in other words, we'll need to get to the top floor to restore the Integrity Knights' memories.","ja":"てことは……整合騎士を元に戻すためには最上階まで到達しなきゃいけないってわけか……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2323#originalText","id":"talk.ch6_2_2323","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"集成骑士可不是好应付的对手， 你最好不要有只打败 而不杀掉他们的想法。","en":"Integrity Knights are fierce. It's unlikely you can breach their defenses without killing them.","ja":"整合騎士は殺さずに勝とうなどという甘い考えが通じる相手ではないぞ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2324#originalText","id":"talk.ch6_2_2324","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"但是，如果爱丽丝出现了呢……？ 我是为了夺回她才来这里的啊。","en":"But what if one of them is Alice? Saving her is the entire reason I came here.","ja":"でも、もしアリスが出てきたら……?僕はアリスを取り戻すためにここまで来たんです"},"kind":"dialogue"},{"uid":"talk.ch6_2_2325#originalText","id":"talk.ch6_2_2325","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"嗯……说得也是。尤吉欧，我也理解你的目的。","en":"Indeed... Eugeo, I understand your mission and I empathize.","ja":"ふむ……そうじゃなユージオよ、そなたの目的はわしも理解しておる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2326#originalText","id":"talk.ch6_2_2326","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"──好吧， 如果集成骑士爱丽丝阻挡在你面前， 你就用这个吧。","en":"Very well. If Alice is one of the Knights who stands in your way, use this.","ja":"――よかろう、もし整合騎士アリスがそなたの前に立ちはだかったならばこれを使うがよい"},"kind":"dialogue"},{"uid":"talk.ch6_2_2327#originalText","id":"talk.ch6_2_2327","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这是……？","en":"What is this?","ja":"これは……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2328#originalText","id":"talk.ch6_2_2328","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"被它刺中的人和我之间 会出现一条无法切断的通道。","en":"Whoever is stabbed by this will be connected to me by an unbreakable link.","ja":"それに刺された者はわしとの間に切断不可能の経路が接続される"},"kind":"dialogue"},{"uid":"talk.ch6_2_2329#originalText","id":"talk.ch6_2_2329","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"也就是说， 我的神圣术一定能击中那个人。","en":"Which means, any Sacred Arts I perform will strike true.","ja":"つまりわしの神聖術が必中となるわけじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2330#originalText","id":"talk.ch6_2_2330","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"尤吉欧， 你就用这把剑刺中集成骑士爱丽丝 身体的任何一处吧。","en":"Eugeo, stab Alice anywhere on her body with that dagger.","ja":"ユージオよ整合騎士アリスの体のどこでも構わんからそれを刺せ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2331#originalText","id":"talk.ch6_2_2331","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"在那个瞬间，我会施术让爱丽丝 陷入深沉的睡眠当中…… 直到你们取回她的记忆。","en":"Then, I can put her into a deep sleep until you boys can retrieve her memory.","ja":"その瞬間、わしの術でアリスを深い眠りに導こう……おぬしらが彼女の記憶を取り戻すまで"},"kind":"dialogue"},{"uid":"talk.ch6_2_2332#originalText","id":"talk.ch6_2_2332","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2333#originalText","id":"talk.ch6_2_2333","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我明白了。如果无法说服爱丽丝， 我就会使用这把短剑。","en":"Understood. If I can't convince Alice to listen, I'll stab her with this.","ja":"解りました。アリスに説得が通じなかったらその時はこれを使わせてもらいます"},"kind":"dialogue"},{"uid":"talk.ch6_2_2334#originalText","id":"talk.ch6_2_2334","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"这个原本是准备拿来对付 亚多米尼史特蕾达而生成的。","en":"I originally built these to use against Administrator.","ja":"もともとは対アドミニストレータ用に生成したものじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2335#originalText","id":"talk.ch6_2_2335","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"其中一把本来是备用的， 不过只要一次成功就没问题了。","en":"I'd originally intended this one to be a spare, but just make sure you succeed on the first try.","ja":"1本は予備のつもりじゃったがなに、1度で成功すれば問題はない"},"kind":"dialogue"},{"uid":"talk.ch6_2_2336#originalText","id":"talk.ch6_2_2336","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔…… 我还真是责任重大……","en":"Yikes... That's a lot of responsibility we're carrying.","ja":"う……責任重大だな……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2337#originalText","id":"talk.ch6_2_2337","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"还有，我能帮你们的， 就只有给予你们和集成骑士对等的 装备而已。","en":"All I can do for you now is equip you with the weapon you'll need to stand against an Integrity Knight.","ja":"あとわしがおぬしらにしてやれるのは整合騎士と対等の装備を与えることくらいのものじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2338#originalText","id":"talk.ch6_2_2338","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你和尤吉欧不是都有强大的爱剑吗？ 我会协助你们把剑拿回来。","en":"I will help you both retrieve the powerful swords you love so much.","ja":"おぬしとユージオには強力な愛剣があるじゃろうそれを取り戻せるよう協力してやる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2339#originalText","id":"talk.ch6_2_2339","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我的蓝蔷薇之剑…… 还有桐人的黑剑吗！？","en":"My Blue Rose Sword... and Kirito's black sword?","ja":"僕の青薔薇の剣と……キリトの黒いやつを!?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2340#originalText","id":"talk.ch6_2_2340","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你们的剑应该是收纳在 圣堂第3层的装备保管库里。","en":"Your swords are most likely in the armory on the third floor.","ja":"おそらく、そなたらの剣はカセドラルの3階にある武具保管庫に収納されておるはずじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2341#originalText","id":"talk.ch6_2_2341","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"顺便问一下， 亚多米尼史特蕾达的房间在第几层啊？","en":"Incidentally, which floor is Administrator's room on?","ja":"ちなみにアドミニストレータの部屋ってのは何階なんだ?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2342#originalText","id":"talk.ch6_2_2342","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"中央圣堂每年都在增高……","en":"Central Cathedral keeps growing taller every year...","ja":"セントラル・カセドラルは年々上昇を続けておるからな……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2342_2#originalText","id":"talk.ch6_2_2342_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"所以现在应该接近100层了……","en":"Her room is around the 100th floor by now.","ja":"現在では100階に迫っておるはず……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2343#originalText","id":"talk.ch6_2_2343","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"一百……","en":"Agh!","ja":"ひゃっ……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2344#originalText","id":"talk.ch6_2_2344","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"很遗憾， 你们还得做一件事。","en":"There is, unfortunately, one other task you must accomplish.","ja":"残念じゃがもうひとつせねばならんことがあるぞ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2345#originalText","id":"talk.ch6_2_2345","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦……什、什么事？","en":"Huh? W-what is it?","ja":"え……な、何?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2346#originalText","id":"talk.ch6_2_2346","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你们的剑确实相当强， 但光靠它们还是赢不了集成骑士。","en":"Your swords are indeed powerful, but they are insufficient to defeat Integrity Knights.","ja":"おぬしらの剣は確かに強力じゃがそれだけでは整合騎士たちには勝てん"},"kind":"dialogue"},{"uid":"talk.ch6_2_2347#originalText","id":"talk.ch6_2_2347","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"因为那群家伙有让武器性能 增加好几倍的恐怖技能。","en":"That is because they have the terrifying technique that multiplies their weapons' power.","ja":"なぜなら連中には武器の性能を数倍に増幅する恐るべき技があるからじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2348#originalText","id":"talk.ch6_2_2348","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊…… 难道是《武装完全支配术》吗……？","en":"Oh...do you mean, \"Perfect Weapon Control\"?","ja":"あ……もしかして《武装完全支配術》ですか……?"},"kind":"dialogue"},{"uid":"talk.ch6_2_2349#originalText","id":"talk.ch6_2_2349","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"神器级的武器继承了大部分 成为代价的物品原本的性质。","en":"Divine weapons take on the characteristics of the objects from which they're fashioned.","ja":"神器級の武器は代償となったオブジェクトの性質を濃く受け継いでおる"},"kind":"dialogue"},{"uid":"talk.ch6_2_2350#originalText","id":"talk.ch6_2_2350","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"完全支配术说起来， 就是完全解放《武器的记忆》，","en":"Perfect Control can completely release a \"weapon's memories,\" in a way,","ja":"完全支配術は、言うなれば"},"kind":"dialogue"},{"uid":"talk.ch6_2_2351#originalText","id":"talk.ch6_2_2351","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"借此实现原本难以达成的 超攻击力。","en":"unleashing attack powers that  should be impossible.","ja":"《武器の記憶》を全解放することで本来有り得ない超攻撃力を実現するものじゃ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2352#originalText","id":"talk.ch6_2_2352","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你们两个都闭上眼睛， 在脑中想像自己的剑。","en":"Close your eyes and visualize your swords.","ja":"ふたりとも目を閉じて己の剣を思い浮かべよ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2303#originalText","id":"talk.ch6_2_2303","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊──她叫做卡迪娜尔， 是被最高司祭亚多米尼史特蕾达","en":"Oh, her name is Cardinal. She's the other Pontifex,","ja":"あー、この人の名前はカーディナル"},"kind":"dialogue"},{"uid":"talk.ch6_2_2353#originalText","id":"talk.ch6_2_2353","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"好，可以了。","en":"Good. You may open your eyes now.","ja":"よし、いいぞ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2354#originalText","id":"talk.ch6_2_2354","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"要好好记住喔。","en":"Memorize that thoroughly.","ja":"しっかり覚えておくのじゃぞ"},"kind":"dialogue"},{"uid":"talk.ch6_2_2355#originalText","id":"talk.ch6_2_2355","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"尤吉欧……还有桐人， 世界的命运就交付在 你们两个人手上了。","en":"Eugeo, Kirito, the fate of the world now lies in your hands.","ja":"ユージオ……そしてキリトよ世界の命運は今やそなたらふたりに託された"},"kind":"dialogue"},{"uid":"talk.ch6_2_2356#originalText","id":"talk.ch6_2_2356","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"它究竟是会被地狱的业火包围…… 还是沉入完全的虚无当中， 又或者是──能找到第三条出路呢？","en":"Will the world be shrouded in hellfire, returned to nothingness, or a third possibility...","ja":"地獄の業火に包まれるか……全き虚無に沈むかあるいは――第三の道を見出すか"},"kind":"dialogue"},{"uid":"talk.ch6_2_2357#originalText","id":"talk.ch6_2_2357","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我已经把该说的全说了， 也把该给的全给你们了。","en":"I have told you everything I know and given you everything I can.","ja":"わしはもはや、告げるべき全てを告げ与えるべき全てを与えた"},"kind":"dialogue"},{"uid":"talk.ch6_2_2357_2#originalText","id":"talk.ch6_2_2357_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你们只要走在自己相信的道路上就好。","en":"Let your faith guide you now.","ja":"あとはただ、信じる道を行けばよい"},"kind":"dialogue"},{"uid":"talk.ch6_2_2358#originalText","id":"talk.ch6_2_2358","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……真的很谢谢妳。我们一定会到达圣堂最上层……","en":"Thank you so much. We will make it to the top floor...","ja":"……ありがとうございますきっとカセドラルのいちばん上まで辿り着いて……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2358_2#originalText","id":"talk.ch6_2_2358_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"然后让爱丽丝恢复原状。","en":"We will return Alice to normal.","ja":"アリスを元に戻してみせます"},"kind":"dialogue"},{"uid":"talk.ch6_2_2359#originalText","id":"talk.ch6_2_2359","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……","en":"...","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch6_2_2360#originalText","id":"talk.ch6_2_2360","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"那么…… 出发吧！","en":"Well, then...Go now.","ja":"では……行くのじゃ!"},"kind":"dialogue"}]};
